python3 << 'PYEOF'
import json
import subprocess
import sys

tests = [
    # Test 1: Exactly 64 character field (should pass)
    {
        "name": "64-char column name",
        "input": {
            "pipeline": {"steps": [{"op": "select", "columns": ["x" * 64]}]},
            "dataset": []
        },
        "should_pass": True
    },
    # Test 2: 65 character field (should fail)
    {
        "name": "65-char column name",
        "input": {
            "pipeline": {"steps": [{"op": "select", "columns": ["x" * 65]}]},
            "dataset": []
        },
        "should_pass": False
    },
    # Test 3: Control character in where
    {
        "name": "newline in where",
        "input": {
            "pipeline": {"steps": [{"op": "filter", "where": "id\n> 10"}]},
            "dataset": []
        },
        "should_pass": False
    },
    # Test 4: Normal operations with small strings
    {
        "name": "normal operations",
        "input": {
            "pipeline": {"steps": [
                {"op": "select", "columns": ["id"]},
                {"op": "filter", "where": "id > 0"},
                {"op": "map", "as": "doubled", "expr": "id * 2"},
                {"op": "rename", "from": "doubled", "to": "x2"},
                {"op": "limit", "n": 10}
            ]},
            "dataset": [{"id": 1}]
        },
        "should_pass": True
    },
    # Test 5: Branch with control character in when
    {
        "name": "tab in branch when",
        "input": {
            "pipeline": {"steps": [
                {"op": "branch", "branches": [
                    {"when": "id\t> 5", "steps": [{"op": "limit", "n": 1}]}
                ]}
            ]},
            "dataset": []
        },
        "should_pass": False
    },
    # Test 6: Rename mapping with over-limit value
    {
        "name": "over-limit mapping value",
        "input": {
            "pipeline": {"steps": [
                {"op": "rename", "mapping": {"old": "x" * 65}}
            ]},
            "dataset": []
        },
        "should_pass": False
    },
]

passed = 0
failed = 0

for test in tests:
    result = subprocess.run(
        ['python', 'etl_pipeline.py'],
        input=json.dumps(test["input"]),
        capture_output=True,
        text=True
    )

    output = json.loads(result.stdout)
    test_passed = (output["status"] == "ok") == test["should_pass"]

    if test_passed:
        passed += 1
        print(f"✓ {test['name']}")
    else:
        failed += 1
        print(f"✗ {test['name']}")
        print(f"  Expected: {'pass' if test['should_pass'] else 'fail'}")
        print(f"  Got: {output['status']}")

print(f"\n{passed} passed, {failed} failed")
sys.exit(0 if failed == 0 else 1)
PYEOF
